  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }

  1→//! Platform-specific shell detection.
  2→
  3→use std::path::PathBuf;
  4→
  5→/// Information about the current shell environment.
  6→#[derive(Debug, Clone)]
  7→pub struct ShellInfo {
  8→    /// Shell executable path.
  9→    pub executable: PathBuf,
 10→
 11→    /// Shell name (bash, zsh, fish, powershell, cmd).
 12→    pub name: ShellType,
 13→
 14→    /// Config files that affect this shell.
 15→    pub config_files: Vec<PathBuf>,
 16→
 17→    /// Command to reload the shell.
 18→    pub reload_command: String,
 19→}
 20→
 21→/// Known shell types.
 22→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 23→pub enum ShellType {
 24→    Bash,
 25→    Zsh,
 26→    Fish,
 27→    PowerShell,
 28→    Cmd,
 29→    Unknown,
 30→}
 31→
 32→impl ShellType {
 33→    /// Parse shell type from executable name.
 34→    pub fn from_executable(exe: &str) -> Self {
 35→        let name = std::path::Path::new(exe)
 36→            .file_stem()
 37→            .and_then(|s| s.to_str())
 38→            .unwrap_or("")
 39→            .to_lowercase();
 40→
 41→        match name.as_str() {
 42→            "bash" => ShellType::Bash,
 43→            "zsh" => ShellType::Zsh,
 44→            "fish" => ShellType::Fish,
 45→            "powershell" | "pwsh" => ShellType::PowerShell,
 46→            "cmd" => ShellType::Cmd,
 47→            _ => ShellType::Unknown,
 48→        }
 49→    }
 50→}
 51→
 52→/// Detect the current shell environment.
 53→pub fn detect_shell() -> ShellInfo {
 54→    let executable = get_shell_executable();
 55→    let shell_type = ShellType::from_executable(&executable.to_string_lossy());
 56→
 57→    ShellInfo {
 58→        executable: executable.clone(),
 59→        name: shell_type,
 60→        config_files: get_config_files(shell_type),
 61→        reload_command: get_reload_command(shell_type, &executable),
 62→    }
 63→}
 64→
 65→fn get_shell_executable() -> PathBuf {
 66→    if cfg!(target_os = "windows") {
 67→        std::env::var("COMSPEC")
 68→            .map(PathBuf::from)
 69→            .unwrap_or_else(|_| PathBuf::from("cmd.exe"))
 70→    } else {
 71→        std::env::var("SHELL")
 72→            .map(PathBuf::from)
 73→            .unwrap_or_else(|_| PathBuf::from("/bin/sh"))
 74→    }
 75→}
 76→
 77→fn get_config_files(shell_type: ShellType) -> Vec<PathBuf> {
 78→    let home = dirs::home_dir().unwrap_or_default();
 79→
 80→    match shell_type {
 81→        ShellType::Bash => vec![
 82→            home.join(".bashrc"),
 83→            home.join(".bash_profile"),
 84→            home.join(".profile"),
 85→        ],
 86→        ShellType::Zsh => vec![
 87→            home.join(".zshrc"),
 88→            home.join(".zprofile"),
 89→            home.join(".zshenv"),
 90→        ],
 91→        ShellType::Fish => vec![home.join(".config/fish/config.fish")],
 92→        ShellType::PowerShell => {
 93→            if let Some(docs) = dirs::document_dir() {
 94→                vec![
 95→                    docs.join("PowerShell/Microsoft.PowerShell_profile.ps1"),
 96→                    docs.join("WindowsPowerShell/Microsoft.PowerShell_profile.ps1"),
 97→                ]
 98→            } else {
 99→                vec![]
100→            }
101→        }
102→        ShellType::Cmd | ShellType::Unknown => vec![],
103→    }
104→}
105→
106→fn get_reload_command(shell_type: ShellType, executable: &std::path::Path) -> String {
107→    match shell_type {
108→        ShellType::Bash | ShellType::Zsh => {
109→            format!("exec {} && bivvy run --continue", executable.display())
110→        }
111→        ShellType::Fish => "exec fish && bivvy run --continue".to_string(),
112→        ShellType::PowerShell => "& $PROFILE; bivvy run --continue".to_string(),
113→        ShellType::Cmd => "start cmd /k \"bivvy run --continue\"".to_string(),
114→        ShellType::Unknown => {
115→            "# Please restart your shell and run: bivvy run --continue".to_string()
116→        }
117→    }
118→}
