  1→//! Install method detection.
  2→//!
  3→//! Detects how bivvy was installed to determine the update mechanism.
  4→
  5→use std::env;
  6→use std::path::{Path, PathBuf};
  7→use std::process::Command;
  8→
  9→/// How bivvy was installed.
 10→#[derive(Debug, Clone, PartialEq, Eq)]
 11→pub enum InstallMethod {
 12→    /// Installed via cargo install
 13→    Cargo,
 14→    /// Installed via Homebrew
 15→    Homebrew,
 16→    /// Downloaded binary or built from source
 17→    Manual { path: PathBuf },
 18→    /// Could not determine install method
 19→    Unknown,
 20→}
 21→
 22→impl InstallMethod {
 23→    /// Get the update command for this install method.
 24→    pub fn update_command(&self) -> Option<String> {
 25→        match self {
 26→            InstallMethod::Cargo => Some("cargo install bivvy --force".to_string()),
 27→            InstallMethod::Homebrew => Some("brew upgrade bivvy".to_string()),
 28→            InstallMethod::Manual { .. } => None,
 29→            InstallMethod::Unknown => None,
 30→        }
 31→    }
 32→
 33→    /// Check if this method supports automatic updates.
 34→    pub fn supports_auto_update(&self) -> bool {
 35→        matches!(self, InstallMethod::Cargo | InstallMethod::Homebrew)
 36→    }
 37→
 38→    /// Get a human-readable name for this install method.
 39→    pub fn name(&self) -> &str {
 40→        match self {
 41→            InstallMethod::Cargo => "cargo",
 42→            InstallMethod::Homebrew => "homebrew",
 43→            InstallMethod::Manual { .. } => "manual",
 44→            InstallMethod::Unknown => "unknown",
 45→        }
 46→    }
 47→}
 48→
 49→/// Detect how bivvy was installed.
 50→pub fn detect_install_method() -> InstallMethod {
 51→    // Get the current executable path
 52→    let exe_path = match env::current_exe() {
 53→        Ok(path) => path,
 54→        Err(_) => return InstallMethod::Unknown,
 55→    };
 56→
 57→    // Check if it's in cargo bin directory
 58→    if is_cargo_install(&exe_path) {
 59→        return InstallMethod::Cargo;
 60→    }
 61→
 62→    // Check if it's managed by Homebrew
 63→    if is_homebrew_install(&exe_path) {
 64→        return InstallMethod::Homebrew;
 65→    }
 66→
 67→    // Manual install (downloaded binary or built from source)
 68→    InstallMethod::Manual { path: exe_path }
 69→}
 70→
 71→fn is_cargo_install(exe_path: &Path) -> bool {
 72→    // Check if executable is in ~/.cargo/bin/
 73→    if let Some(home) = dirs::home_dir() {
 74→        let cargo_bin = home.join(".cargo").join("bin");
 75→        if exe_path.starts_with(&cargo_bin) {
 76→            return true;
 77→        }
 78→    }
 79→
 80→    // Check CARGO_HOME environment variable
 81→    if let Ok(cargo_home) = env::var("CARGO_HOME") {
 82→        let cargo_bin = PathBuf::from(cargo_home).join("bin");
 83→        if exe_path.starts_with(&cargo_bin) {
 84→            return true;
 85→        }
 86→    }
 87→
 88→    false
 89→}
 90→
 91→fn is_homebrew_install(exe_path: &Path) -> bool {
 92→    // Check common Homebrew paths
 93→    let homebrew_paths = [
 94→        "/usr/local/Cellar/",          // Intel macOS
 95→        "/opt/homebrew/Cellar/",       // ARM macOS
 96→        "/home/linuxbrew/.linuxbrew/", // Linux
 97→    ];
 98→
 99→    let exe_str = exe_path.to_string_lossy();
100→    for prefix in &homebrew_paths {
101→        if exe_str.starts_with(prefix) {
102→            return true;
103→        }
104→    }
105→
106→    // Also check if it's a symlink from Homebrew bin
107→    let homebrew_bins = ["/usr/local/bin/bivvy", "/opt/homebrew/bin/bivvy"];
108→
109→    for bin in &homebrew_bins {
110→        if exe_path.to_string_lossy() == *bin {
111→            // Check if it's actually a Homebrew-managed binary
112→            if let Ok(output) = Command::new("brew")
113→                .args(["list", "--formula", "bivvy"])
114→                .output()
115→            {
116→                if output.status.success() {
117→                    return true;
118→                }
119→            }
120→        }

  1→//! Failure telemetry: scrubbing, consent, and local report storage.
  2→//!
  3→//! After a successful recovery (step eventually passes after retry, fix,
  4→//! or shell), optionally prompts the user to share a scrubbed failure report.
  5→//! Reports are stored locally as YAML files under `~/.bivvy/failure-reports/`.
  6→
  7→use std::collections::HashMap;
  8→use std::fmt;
  9→use std::path::{Path, PathBuf};
 10→use std::sync::LazyLock;
 11→
 12→use regex::Regex;
 13→use serde::{Deserialize, Serialize};
 14→
 15→use crate::error::Result;
 16→use crate::secrets::mask::OutputMasker;
 17→use crate::secrets::pattern::SecretMatcher;
 18→use crate::ui::{Prompt, PromptOption, PromptType, UserInterface};
 19→
 20→/// Regex for scrubbing filesystem paths.
 21→static PATH_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 22→    Regex::new(r"(?:/Users/[^\s:]+|/home/[^\s:]+|/tmp/[^\s:]+|C:\\Users\\[^\s:]+)")
 23→        .expect("PATH_REGEX must compile")
 24→});
 25→
 26→/// Regex for scrubbing token-like strings (hex > 16 chars, base64 blobs, known prefixes).
 27→static TOKEN_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 28→    Regex::new(r"(?:ghp_[A-Za-z0-9]{36,}|gho_[A-Za-z0-9]{36,}|sk-[A-Za-z0-9]{20,}|xoxb-[A-Za-z0-9\-]+|xoxp-[A-Za-z0-9\-]+|[A-Fa-f0-9]{32,}|[A-Za-z0-9+/]{40,}={0,2})")
 29→        .expect("TOKEN_REGEX must compile")
 30→});
 31→
 32→/// Maximum length of scrubbed error output in a report.
 33→const MAX_ERROR_LENGTH: usize = 500;
 34→
 35→/// User's telemetry consent preference.
 36→#[derive(Debug, Clone, PartialEq, Eq)]
 37→pub enum TelemetryConsent {
 38→    /// Send this one report.
 39→    Send,
 40→    /// Don't send this report.
 41→    NoThanks,
 42→    /// Always send (save preference).
 43→    Always,
 44→    /// Never ask again (save preference).
 45→    Never,
 46→}
 47→
 48→impl fmt::Display for TelemetryConsent {
 49→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 50→        match self {
 51→            TelemetryConsent::Send => write!(f, "send"),
 52→            TelemetryConsent::NoThanks => write!(f, "no_thanks"),
 53→            TelemetryConsent::Always => write!(f, "always"),
 54→            TelemetryConsent::Never => write!(f, "never"),
 55→        }
 56→    }
 57→}
 58→
 59→/// A scrubbed failure report.
 60→#[derive(Debug, Clone, Serialize, Deserialize)]
 61→pub struct FailureReport {
 62→    /// Step name (e.g., "bundler").
 63→    pub step_name: String,
 64→    /// Scrubbed command (e.g., "bundle install").
 65→    pub command_scrubbed: String,
 66→    /// Process exit code.
 67→    pub exit_code: Option<i32>,
 68→    /// Scrubbed error output (first 500 chars).
 69→    pub error_scrubbed: String,
 70→    /// Recovery action taken (e.g., "retry", "shell → retry").
 71→    pub recovery_action: String,
 72→    /// Bivvy version.
 73→    pub bivvy_version: String,
 74→    /// Platform string (e.g., "macos-aarch64").
 75→    pub platform: String,
 76→}
 77→
 78→/// Scrub sensitive data from text for telemetry.
 79→///
 80→/// 1. Masks known secret env var values using `OutputMasker`
 81→/// 2. Replaces filesystem paths with `[PATH]`
 82→/// 3. Replaces token-like strings with `[REDACTED]`
 83→/// 4. Truncates to `MAX_ERROR_LENGTH` chars
 84→pub fn scrub_for_telemetry(input: &str, step_env: &HashMap<String, String>) -> String {
 85→    let matcher = SecretMatcher::with_builtins();
 86→    let mut masker = OutputMasker::new();
 87→
 88→    // Mask known secret env var values
 89→    for (key, value) in step_env {
 90→        if matcher.is_secret(key) && !value.is_empty() {
 91→            masker.add_secret(value);
 92→        }
 93→    }
 94→
 95→    let mut result = masker.mask(input);
 96→
 97→    // Scrub filesystem paths
 98→    result = PATH_REGEX.replace_all(&result, "[PATH]").to_string();
 99→
100→    // Scrub token-like strings

  1→//! Version checking against latest release.
  2→
  3→use anyhow::{Context, Result};
  4→use chrono::{DateTime, Utc};
  5→use serde::{Deserialize, Serialize};
  6→use std::fs;
  7→use std::path::PathBuf;
  8→
  9→/// Current version of bivvy.
 10→pub const VERSION: &str = env!("CARGO_PKG_VERSION");
 11→
 12→/// GitHub API URL for releases.
 13→const GITHUB_API_URL: &str = "https://api.github.com/repos/bivvy-dev/bivvy/releases/latest";
 14→
 15→/// How often to check for updates (1 day).
 16→const CHECK_INTERVAL_SECS: i64 = 86400;
 17→
 18→/// Information about an available update.
 19→#[derive(Debug, Clone, Serialize, Deserialize)]
 20→pub struct UpdateInfo {
 21→    /// Current version.
 22→    pub current: String,
 23→    /// Latest available version.
 24→    pub latest: String,
 25→    /// Whether an update is available.
 26→    pub update_available: bool,
 27→    /// Release URL.
 28→    pub release_url: Option<String>,
 29→    /// When this check was performed.
 30→    pub checked_at: DateTime<Utc>,
 31→}
 32→
 33→/// Cached update check result.
 34→#[derive(Debug, Clone, Serialize, Deserialize)]
 35→struct UpdateCache {
 36→    /// Last update info.
 37→    info: UpdateInfo,
 38→    /// When the cache was written.
 39→    cached_at: DateTime<Utc>,
 40→}
 41→
 42→/// Check for available updates.
 43→///
 44→/// Returns cached result if within check interval.
 45→pub fn check_for_updates() -> Option<UpdateInfo> {
 46→    // Check cache first
 47→    if let Some(cached) = load_cache() {
 48→        let age = Utc::now()
 49→            .signed_duration_since(cached.cached_at)
 50→            .num_seconds();
 51→        if age < CHECK_INTERVAL_SECS {
 52→            return Some(cached.info);
 53→        }
 54→    }
 55→
 56→    // Fetch latest version
 57→    match fetch_latest_version() {
 58→        Ok(info) => {
 59→            // Cache the result
 60→            let _ = save_cache(&info);
 61→            Some(info)
 62→        }
 63→        Err(_) => {
 64→            // Return cached result even if expired
 65→            load_cache().map(|c| c.info)
 66→        }
 67→    }
 68→}
 69→
 70→/// Check for updates without using cache.
 71→pub fn check_for_updates_fresh() -> Result<UpdateInfo> {
 72→    fetch_latest_version()
 73→}
 74→
 75→/// Fetch the latest version from GitHub.
 76→fn fetch_latest_version() -> Result<UpdateInfo> {
 77→    let client = reqwest::blocking::Client::builder()
 78→        .user_agent("bivvy")
 79→        .timeout(std::time::Duration::from_secs(10))
 80→        .build()?;
 81→
 82→    let response: serde_json::Value = client
 83→        .get(GITHUB_API_URL)
 84→        .send()?
 85→        .json()
 86→        .context("Failed to parse GitHub API response")?;
 87→
 88→    let tag = response["tag_name"]
 89→        .as_str()
 90→        .context("No tag_name in response")?
 91→        .trim_start_matches('v');
 92→
 93→    let release_url = response["html_url"].as_str().map(String::from);
 94→
 95→    let update_available = is_newer_version(tag, VERSION);
 96→
 97→    Ok(UpdateInfo {
 98→        current: VERSION.to_string(),
 99→        latest: tag.to_string(),
100→        update_available,

100→        update_available,
101→        release_url,
102→        checked_at: Utc::now(),
103→    })
104→}
105→
106→/// Compare versions to check if `latest` is newer than `current`.
107→fn is_newer_version(latest: &str, current: &str) -> bool {
108→    let parse_version = |v: &str| -> Vec<u32> {
109→        v.split('.')
110→            .take(3)
111→            .filter_map(|s| s.parse().ok())
112→            .collect()
113→    };
114→
115→    let latest_parts = parse_version(latest);
116→    let current_parts = parse_version(current);
117→
118→    // Compare component by component
119→    for (l, c) in latest_parts.iter().zip(current_parts.iter()) {
120→        if l > c {
121→            return true;
122→        }
123→        if l < c {
124→            return false;
125→        }
126→    }
127→
128→    // If all components equal, check if latest has more components
129→    latest_parts.len() > current_parts.len()
130→}
