  1→//! Shell reload resume state management.
  2→//!
  3→//! This module provides functionality for saving and restoring execution
  4→//! state across shell reloads.
  5→
  6→use anyhow::Result;
  7→use serde::{Deserialize, Serialize};
  8→use std::path::PathBuf;
  9→use std::sync::Mutex;
 10→
 11→// Override path for testing
 12→static STATE_PATH_OVERRIDE: Mutex<Option<PathBuf>> = Mutex::new(None);
 13→
 14→/// State saved for resuming after shell reload.
 15→///
 16→/// # Example
 17→///
 18→/// ```no_run
 19→/// use bivvy::shell::ResumeState;
 20→/// use std::path::PathBuf;
 21→///
 22→/// // Create a resume state
 23→/// let state = ResumeState {
 24→///     project_root: PathBuf::from("/test/project"),
 25→///     workflow: "default".to_string(),
 26→///     completed_steps: vec!["step1".to_string()],
 27→///     pending_step: "step2".to_string(),
 28→///     timestamp: chrono::Utc::now(),
 29→/// };
 30→///
 31→/// // Save state to disk
 32→/// state.save().unwrap();
 33→///
 34→/// // Later, load state back
 35→/// let loaded = ResumeState::load().unwrap().unwrap();
 36→/// assert_eq!(loaded.workflow, "default");
 37→/// ```
 38→#[derive(Debug, Clone, Serialize, Deserialize)]
 39→pub struct ResumeState {
 40→    /// Project root path.
 41→    pub project_root: PathBuf,
 42→    /// Workflow being executed.
 43→    pub workflow: String,
 44→    /// Steps that have been completed.
 45→    pub completed_steps: Vec<String>,
 46→    /// Step that triggered the reload.
 47→    pub pending_step: String,
 48→    /// Timestamp when reload was requested.
 49→    pub timestamp: chrono::DateTime<chrono::Utc>,
 50→}
 51→
 52→impl ResumeState {
 53→    /// Save resume state to disk.
 54→    pub fn save(&self) -> Result<PathBuf> {
 55→        let path = Self::state_path();
 56→        if let Some(parent) = path.parent() {
 57→            std::fs::create_dir_all(parent)?;
 58→        }
 59→        let content = serde_json::to_string_pretty(self)?;
 60→        std::fs::write(&path, content)?;
 61→        Ok(path)
 62→    }
 63→
 64→    /// Load resume state if it exists.
 65→    pub fn load() -> Result<Option<Self>> {
 66→        let path = Self::state_path();
 67→        if !path.exists() {
 68→            return Ok(None);
 69→        }
 70→        let content = std::fs::read_to_string(&path)?;
 71→        let state: Self = serde_json::from_str(&content)?;
 72→        Ok(Some(state))
 73→    }
 74→
 75→    /// Clear saved resume state.
 76→    pub fn clear() -> Result<()> {
 77→        let path = Self::state_path();
 78→        if path.exists() {
 79→            std::fs::remove_file(&path)?;
 80→        }
 81→        Ok(())
 82→    }
 83→
 84→    /// Check if there is a resume state available.
 85→    pub fn exists() -> bool {
 86→        Self::state_path().exists()
 87→    }
 88→
 89→    /// Get the resume state file path.
 90→    fn state_path() -> PathBuf {
 91→        if let Ok(guard) = STATE_PATH_OVERRIDE.lock() {
 92→            if let Some(ref path) = *guard {
 93→                return path.clone();
 94→            }
 95→        }
 96→        dirs::data_local_dir()
 97→            .unwrap_or_else(|| PathBuf::from("~/.local/share"))
 98→            .join("bivvy")
 99→            .join("resume-state.json")
100→    }
101→
102→    /// Set the state path override (for testing).
103→    #[cfg(test)]
104→    pub fn set_state_path_override(path: Option<PathBuf>) {
105→        if let Ok(mut guard) = STATE_PATH_OVERRIDE.lock() {
106→            *guard = path;
107→        }
108→    }
109→}
110→
111→/// Options for shell reload prompt.
112→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
113→pub enum ReloadChoice {
114→    /// Reload shell and continue automatically.
115→    ReloadAndContinue,
116→    /// Exit and let user reload manually.
117→    ExitManual,
118→    /// Skip the step requiring reload.
119→    Skip,
120→}
121→
122→impl ReloadChoice {
123→    /// Get the human-readable description for this choice.
124→    pub fn description(&self) -> &'static str {
125→        match self {
126→            Self::ReloadAndContinue => "Reload shell and continue (recommended)",
127→            Self::ExitManual => "Exit and reload manually",
128→            Self::Skip => "Skip this step",
129→        }
130→    }
131→}
132→
133→#[cfg(test)]
134→mod tests {
135→    use super::*;
136→    use std::sync::Mutex;
137→    use tempfile::TempDir;
138→
139→    // Mutex to serialize tests that use state path override
140→    static TEST_MUTEX: Mutex<()> = Mutex::new(());
141→
142→    fn with_temp_state<F, R>(f: F) -> R
143→    where
144→        F: FnOnce() -> R,
145→    {
146→        let _guard = TEST_MUTEX.lock().unwrap();
147→        let temp = TempDir::new().unwrap();
148→        let state_path = temp.path().join("resume-state.json");
149→        ResumeState::set_state_path_override(Some(state_path));
150→        let result = f();
151→        ResumeState::set_state_path_override(None);
152→        result
153→    }
