198→            let loaded = ResumeState::load().unwrap();
199→            assert!(loaded.is_none());
200→        });
201→    }
202→
203→    #[test]
204→    fn exists_returns_false_when_no_state() {
205→        with_temp_state(|| {
206→            assert!(!ResumeState::exists());
207→        });
208→    }
