211→    fn reload_choice_descriptions() {
212→        assert!(ReloadChoice::ReloadAndContinue
213→            .description()
214→            .contains("Reload"));
215→        assert!(ReloadChoice::ExitManual.description().contains("Exit"));
216→        assert!(ReloadChoice::Skip.description().contains("Skip"));
217→    }
