fn resolve_path(&self, platform_base: Option<PathBuf>, legacy_subpath: &str) -> PathBuf {
    // 1. If BIVVY_HOME is set, use it
    if let Some(ref home) = self.bivvy_home {
        return home.join(legacy_subpath);
    }

    // 2. Check if legacy path exists and new path doesn't
    if let Some(ref legacy_base) = self.legacy_dir {
        let legacy_path = legacy_base.join(legacy_subpath);
        if legacy_path.exists() {
            if let Some(ref new_base) = platform_base {
                let new_path = new_base.join(APP_NAME).join(legacy_subpath);
                if !new_path.exists() {
                    return legacy_path;
                }
            }
        }
    }

    // 3. Use platform-native path
    platform_base
        .unwrap_or_else(|| PathBuf::from("."))
        .join(APP_NAME)
        .join(legacy_subpath)
}
